const blobDataUrl=blob=>new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=()=>reject(r.error);r.readAsDataURL(blob)});
const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let pendingRestore=null,backupReminderShown=false;
let courses=new Map(),mappingTables=new Map(),learners=[],assessments=[],reviews=[],visits=[],professionalDocuments=[],assessorProfile={key:'assessor-profile',name:'',providerName:'',onboardingComplete:false,storageAccepted:false,signatureSkipped:false,signatureDataUrl:'',signatureType:''},providerLogoUrl='',route={view:'home'},deferredInstallPrompt=null,openLO={practical:null,knowledge:null},calendarMonth=new Date().toISOString().slice(0,7),calendarOpen=false,selectedCalendarDate='';
