const conciseUnitTitles={102:'Health, Safety and Welfare',234:'Masonry Cladding',235:'Masonry Structures',238:'Thin Joint Masonry',303:'Occupational Work Method',300:'Work Activities and Resources',313:'Architectural and Decorative Masonry',502:'Working Relationships',690:'Masonry Repair and Maintenance',701:'Setting Out Masonry',828:'Specialist Masonry Elements',837:'Drainage'};
