async function finishOnboarding(includeLogo=true){try{if(includeLogo&&pendingProviderLogo)await saveLogo(pendingProviderLogo);if(!includeLogo&&pendingProviderLogo){pendingProviderLogo=null;onboardingDraft.providerLogo=null;delete assessorProfile.providerLogo}assessorProfile=profileFromDraft(assessorProfile,onboardingDraft);await put('settings',assessorProfile);pendingProviderLogo=null;closeSheet();go('ready')}catch(error){console.error('Provider logo could not be saved.',error);openSheet('<h2 id=sheet-title>Logo could not be saved</h2><p>Your name and provider details are still here. Retry saving the logo, or finish setup without it.</p><div class=button-row><button class=secondary data-continue-without-logo>Continue Without Logo</button><button class=action data-retry-logo>Retry</button></div>')}}

const learnerCourse=learner=>courseForLearner(courses,learner);
const assessmentLearner=assessment=>learners.find(l=>l.id===assessment?.learnerId);
const assessmentCourse=assessment=>learnerCourse(assessmentLearner(assessment));
const courseMappings=course=>mappingTables.get(course.course.id)||[];
async function init(){courses=await loadCourses();mappingTables=new Map([...courses].map(([id,course])=>[id,isKsbCourse(course)?[]:generateMappings(course)]));await refresh();assessorProfile={...assessorProfile,...(await optionalRead(()=>get('settings','assessor-profile'),null,'assessor profile')||{})};const signature=await optionalRead(()=>get('profileAssets','signature'),null,'saved signature');if(signature?.blob)assessorProfile.signatureDataUrl=await optionalRead(()=>blobDataUrl(signature.blob),'','saved signature image');else if(assessorProfile.signatureBlob&&!assessorProfile.signatureDataUrl)assessorProfile.signatureDataUrl=await optionalRead(()=>blobDataUrl(assessorProfile.signatureBlob),'','legacy saved signature image');const logo=await optionalRead(()=>get('profileAssets','provider-logo'),null,'provider logo');if(logo?.blob)providerLogoUrl=URL.createObjectURL(logo.blob);professionalDocuments=await optionalRead(()=>all('professionalDocuments'),[],'professional documents');if(!assessorProfile.backupReminder){assessorProfile.backupReminder='weekly';assessorProfile.backupReminderStartedAt=new Date().toISOString();await put('settings',assessorProfile)}onboardingDraft=createOnboardingDraft(assessorProfile);onboardingDraft.providerLogo=logo?{key:'provider-logo',type:logo.type,updatedAt:logo.updatedAt}:null;if(!assessorProfile.onboardingComplete&&(learners.length||assessments.length)){assessorProfile.onboardingComplete=true;assessorProfile.migratedExisting=true;await optionalRead(()=>put('settings',assessorProfile),assessorProfile,'migrated assessor profile')}document.body.removeEventListener('click',click);document.body.addEventListener('click',click);wireInstall();if('serviceWorker'in navigator)navigator.serviceWorker.register('./sw.js').catch(error=>console.warn('Assessor+ service worker registration failed.',error));if(!assessorProfile.onboardingComplete)route={view:'onboarding'};render();setTimeout(showBackupReminder,250);}
async function refresh(){[learners,assessments,reviews,visits]=await Promise.all([all('learners'),all('assessments'),all('reviews'),all('visits')]);assessments.forEach(normaliseAssessment);await hydrateMedia(assessments);}
async function hydrateMedia(records){for(const a of records)for(const m of [...(a.media||[]),...(a.knowledgeEvidence||[])]){if(m.url?.startsWith('blob:'))URL.revokeObjectURL(m.url);const stored=await get('media',m.id);m.url=stored?.blob?URL.createObjectURL(stored.blob):'';}}
function go(view,id,primaryUnit){route={view,id,primaryUnit};closeSheet();render();scrollTo(0,0)}
const backToLearnerButton=learnerId=>`<button type=button class="text-button back-control" data-back-learner="${learnerId}">‹ Back to Learner</button>`;
function observationHasUnsavedChanges(a){const saved=assessments.find(x=>x.id===a.id);return !saved||materialAssessmentChanged(saved,a)}
function requestLearnerReturn(learnerId){
 if(route.view==='setup'&&$('#setup-form')?.dataset.dirty==='true')return openDiscardConfirmation(learnerId);
 if(route.view==='observation'){const a=getDraft();sync(a);if(observationHasUnsavedChanges(a))return openDiscardConfirmation(learnerId,a.id)}
 go('learnerProfile',learnerId)
}
function openDiscardConfirmation(learnerId,assessmentId=''){openSheet(`<h2 id=sheet-title>Discard unsaved changes?</h2><p>Your unsaved changes will not be kept.</p><div class=button-row><button class=secondary data-close-sheet>Cancel</button><button class="action confirm-danger" data-confirm-learner-return="${learnerId}" data-discard-assessment="${assessmentId}">Exit</button></div>`)}
async function discardAndReturn(learnerId,assessmentId){if(assessmentId){const a=drafts.get(assessmentId);if(!assessments.some(x=>x.id===assessmentId))for(const m of [...(a?.media||[]),...(a?.knowledgeEvidence||[])])await remove('media',m.id);drafts.delete(assessmentId)}go('learnerProfile',learnerId)}
function toast(t){$('#toast').textContent=t;$('#toast').style.display='block';setTimeout(()=>$('#toast').style.display='none',2200)}
function readUKDate(input,{optional=false}={}){const value=input?.value||'';input?.setCustomValidity(!value&&optional?'':value?'':UK_DATE_VALIDATION_MESSAGE);if(input&&!input.checkValidity()){input.reportValidity();return null}return value;}
function bindUKDateInput(input){input?.addEventListener('input',()=>input.setCustomValidity(''))}
function render(){const f={onboarding,ready,learners:learnerList,learnerProfile,toolkit,settings,assessorProfileView,assessments:assessmentList,setup,observation,matrix,reviewEditor,home,planning}[route.view]||learnerList;$('#app').innerHTML=f(route.id);const learnerViews=new Set(['learners','learnerProfile','assessments','setup','observation','matrix','reviewEditor']),toolViews=new Set(['toolkit','settings','assessorProfileView']);document.querySelectorAll('.bottom-nav button').forEach(button=>{const selected=(button.dataset.view==='home'&&route.view==='home')||(button.dataset.view==='learners'&&learnerViews.has(route.view))||(button.dataset.view==='planning'&&route.view==='planning')||(button.dataset.view==='toolkit'&&toolViews.has(route.view));button.classList.toggle('selected',selected);button.toggleAttribute('aria-current',selected)});document.body.classList.toggle('assessment-open',route.view==='observation');document.body.classList.toggle('onboarding-open',route.view==='onboarding'||route.view==='ready');bind();}
function wireInstall(){const standalone=matchMedia('(display-mode: standalone)').matches||navigator.standalone===true;window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();if(!standalone){deferredInstallPrompt=e;$('#install-app')?.removeAttribute('hidden')}});window.addEventListener('appinstalled',()=>{deferredInstallPrompt=null;$('#install-app')?.setAttribute('hidden','')});if(standalone)$('#install-app')?.setAttribute('hidden','');}

function onboarding(){return `<section class="onboarding card"><small class=eyebrow>WELCOME / PROFILE SETUP</small><h1>Welcome to Assessor+</h1><p class=muted>No account, login or cloud setup. Create your permanent local assessor identity.</p><form id=onboarding-form><label>Assessor Name <em>Required</em><input name=name value="${esc(onboardingDraft.assessorName)}" required autocomplete=name></label><label>College / Training Provider <em>Optional</em><input name=provider value="${esc(onboardingDraft.providerName)}"></label><label class=file-button> ${onboardingDraft.providerLogo?'Logo selected — Replace Logo':'Add Logo'}<input hidden name=logo type=file accept="image/png,image/jpeg,image/webp"></label>${onboardingDraft.providerLogo?'<small class=asset-status>Provider logo selected for this profile</small>':''}<h2>Signature</h2><p class=muted>Draw with a finger, stylus or mouse, then save it.</p>${signatureEditor()}<label class=check-row><input name=skip type=checkbox ${onboardingDraft.signatureSkipped?'checked':''}> Skip signature for now — add it later in Profile</label><aside class=storage-notice><h2>Local Storage Notice</h2><p>All Assessor+ information, assessments, signatures, photos, videos, audio, professional documents and settings are saved locally on this device/browser.</p><p>Nothing is uploaded automatically. Clearing browser/app data or losing the device may remove locally stored information unless a future backup/export system has been used.</p></aside><label class=check-row><input name=accepted type=checkbox required ${onboardingDraft.storageAccepted?'checked':''}> I understand that Assessor+ stores its working data locally on this device.</label><button class=action>Finish Setup</button></form></section>`}
function ready(){return `<section class="onboarding card ready"><span class=ready-mark>✓</span><h1>Assessor+ is ready</h1><p>Your local profile has been saved on this device.</p><button class=action data-start-app>Start Using Assessor+</button></section>`}
const longVisitDate=v=>new Intl.DateTimeFormat('en-GB',{weekday:'long',day:'numeric',month:'long'}).format(new Date(`${v.date}T12:00:00`));
const visitChip=(v,l)=>`<button class="visit-initials ${VISIT_TYPES[v.type]?.colour||'blue'}" title="${esc(l?.name)} — ${esc(VISIT_TYPES[v.type]?.label||'Visit')}" aria-label="Edit ${esc(VISIT_TYPES[v.type]?.label||'visit')} for ${esc(l?.name||'unknown learner')}" data-edit-visit="${v.id}">${learnerInitials(l?.name)}</button>`;
const availabilityChips=date=>learners.flatMap(l=>{const out=[];if(annualLeaveForDate(l,date).length)out.push(`<span class="availability-chip yellow" title="${esc(l.name)} — Annual Leave">${learnerInitials(l.name)}<span class=visually-hidden> Annual Leave</span></span>`);else if(collegeDayForDate(l,date))out.push(`<span class="availability-chip grey" title="${esc(l.name)} — College Day">${learnerInitials(l.name)}<span class=visually-hidden> College Day</span></span>`);return out}).join('');
function bookingAwarenessHtml(l,date,editingId=''){const info=bookingAwareness(l,date,visits.filter(v=>v.id!==editingId),learners),rows=[...info.selectedVisits.map(v=>({...v,learner:l})),...info.otherVisits];return `<aside class=booking-awareness data-booking-awareness><strong>Already planned that day</strong>${rows.length?rows.map(v=>`<small>${esc(v.time||'Time not set')} · ${esc(v.learner?.name||'Unknown learner')} · ${esc(VISIT_TYPES[v.type]?.label||'Visit')}</small>`).join(''):'<small>No assessor visits planned.</small>'}${info.availability.labels.length?`<p class="selected-availability ${info.availability.annualLeave.length?'leave-warning':''}"><strong>Selected learner:</strong> ${info.availability.labels.join(' · ')}</p>`:''}${info.hasClash?'<p class=clash-warning>Clash warning — you can still save this visit deliberately.</p>':''}</aside>`}
function visitForm(l,visit={}){const date=visit.date||new Date().toISOString().slice(0,10);return `<h2 id=sheet-title>${visit.id?'Edit Visit':'Plan Visit'}</h2><p>${esc(l.name)}</p><form id=visit-form data-visit-id="${visit.id||''}" data-learner-id="${l.id}"><label>Date<input name=date ${UK_DATE_INPUT_ATTRIBUTES} value="${date}" required></label>${bookingAwarenessHtml(l,date,visit.id)}<label>Time<input type=time name=time value="${visit.time||'09:00'}" required></label><label>Visit type<select name=type>${Object.entries(VISIT_TYPES).map(([value,x])=>`<option value="${value}" ${visit.type===value?'selected':''}>${x.label}</option>`).join('')}</select></label><label>Location<input name=location value="${esc(visit.location??l.workplace??'')}" required autocomplete=street-address></label><label>Visit note<textarea name=note maxlength=300>${esc(visit.note||'')}</textarea></label><button class=action>Save Visit</button></form>`}
function home(){const active=activeLearners(learners),overview=courseOverview(learners,courses),now=new Date(),soon=new Date(now);soon.setUTCDate(soon.getUTCDate()+14);const attention=[];for(const l of active){const latest=reviewsForLearner(reviews,l.id).find(r=>r.status==='Completed');if(latest?.nextReviewDate){const due=new Date(`${latest.nextReviewDate}T23:59:59`);if(due<now)attention.push({l,text:`Review overdue · ${formatUKDate(latest.nextReviewDate)}`});else if(due<=soon)attention.push({l,text:`Review due soon · ${formatUKDate(latest.nextReviewDate)}`})}if(latest?.apprentice?.concern&&latest.apprentice.concern!=='No concerns')attention.push({l,text:'Outstanding review concern'});if((latest?.targets||[]).some(t=>t.status!=='Completed'))attention.push({l,text:'Outstanding review action'})}const activity=[...reviews.filter(r=>r.status==='Completed').map(r=>({date:r.updatedAt||r.reviewDate,label:'Review completed',learnerId:r.learnerId})),...assessments.map(a=>({date:a.updatedAt||a.date,label:'Observation completed',learnerId:a.learnerId}))].sort((a,b)=>b.date.localeCompare(a.date)).slice(0,5),next=nextVisit(visits,now),nextLearner=learners.find(l=>l.id===next?.learnerId);return `<div class=page-title><div><small class=eyebrow>CASELOAD DASHBOARD</small><h1>Home</h1></div></div><section class="card metric-card"><small>ACTIVE LEARNERS</small><strong>${active.length}</strong></section>${next?`<section class="card next-visit"><small>NEXT VISIT</small><h2>${esc(shortLearnerName(nextLearner?.name))}</h2><p>${VISIT_TYPES[next.type].label}<br>${longVisitDate(next).split(' ')[0]} · ${next.time}</p><button class=secondary data-view=planning>Open Planning</button></section>`:''}<section class=card><h2>Needs Attention</h2>${attention.length?attention.map(x=>`<button class=dashboard-row data-profile="${x.l.id}"><span><strong>${esc(x.l.name)}</strong><small>${esc(x.text)}</small></span><b>›</b></button>`).join(''):'<p class=muted>No items need attention from current records.</p>'}</section><section class=card><h2>Course Overview</h2>${overview.length?overview.map(x=>`<div class=overview-row><span>${esc(x.title)}</span><strong>${x.count}</strong></div>`).join(''):'<p class=muted>No active learners.</p>'}</section><section class=card><h2>Recent Activity</h2>${activity.length?activity.map(x=>{const l=learners.find(y=>y.id===x.learnerId);return `<button class=dashboard-row data-profile="${x.learnerId}"><span><strong>${x.label}</strong><small>${esc(l?.name)} · ${formatUKDate(x.date)}</small></span></button>`}).join(''):'<p class=muted>No completed activity.</p>'}</section>`}
function calendar(){const [year,month]=calendarMonth.split('-').map(Number),first=new Date(Date.UTC(year,month-1,1)),cells=monthCalendarDates(calendarMonth);return `<section class="card month-calendar"><div class=calendar-head><button class=text-button data-calendar-prev aria-label="Previous month">‹</button><h2>${new Intl.DateTimeFormat('en-GB',{month:'long',year:'numeric',timeZone:'UTC'}).format(first)}</h2><button class=text-button data-calendar-next aria-label="Next month">›</button></div><div class=calendar-grid>${['M','T','W','T','F','S','S'].map(d=>`<b>${d}</b>`).join('')}${cells.map(date=>date?`<div class="calendar-day ${selectedCalendarDate===date?'selected':''}" data-date-cell="${date}"><button class=calendar-date data-calendar-date="${date}" aria-label="${formatUKDate(date)}">${Number(date.slice(-2))}</button><div class=calendar-visits>${visitsForDate(visits,date).map(v=>visitChip(v,learners.find(l=>l.id===v.learnerId))).join('')}</div></div>`:'<i aria-hidden=true></i>').join('')}</div>${selectedCalendarDate?`<div class=calendar-selection><h2>${formatUKDate(selectedCalendarDate)}</h2>${visitsForDate(visits,selectedCalendarDate).map(v=>visitCard(v)).join('')||'<p class=muted>No visits planned.</p>'}</div>`:''}</section>`}
function actionIcon(name,path){return `<svg aria-hidden="true" viewBox="0 0 24 24"><path d="${path}"></path></svg><span class=visually-hidden>${name}</span>`}
const visitStatusHtml=(label,record)=>`<button class=visit-work-row data-open-visit-work="${label}"><span><strong>${label}</strong><small>${workStatus(record)}</small></span><b aria-hidden=true>›</b></button>`;
async function updateVisitCompletion(visitId){const v=visits.find(x=>x.id===visitId);if(!v)return;const work=visitWork(v,reviews,assessments),done=v.type==='combined'?work.review?.status==='Completed'&&work.observation?.status==='Completed':v.type==='observation'?work.observation?.status==='Completed':work.review?.status==='Completed';v.status=done?'completed':'planned';await put('visits',v)}
function showVisitChooser(v){const l=learners.find(x=>x.id===v.learnerId),work=visitWork(v,reviews,assessments);openSheet(`<h2 id=sheet-title>${esc(l.name)}</h2><p>${formatUKDate(v.date)} · Review + Observation</p><div class=visit-work-list data-visit-work-id="${v.id}">${visitStatusHtml('Review',work.review)}${visitStatusHtml('Observation',work.observation)}</div>`)}
async function openPlannedVisit(id,part=''){const v=visits.find(x=>x.id===id),l=learners.find(x=>x.id===v?.learnerId);if(!v||!l)return toast('This planned visit cannot be opened');if(v.type==='combined'&&!part)return showVisitChooser(v);if(part==='Review'||v.type==='review'||v.type==='catchup'){let r=reviews.find(x=>x.id===v.reviewId);if(!r){const course=learnerCourse(l),full=latestCompletedReview(reviews,l.id);r=v.type==='catchup'?createCatchUpReview({reviews,learner:l,course,fullReview:full,date:v.date}):createReview({reviews,learner:l,course,assessments,profile:assessorProfile,date:v.date});r.visitId=v.id;r.status='Draft';v.reviewId=r.id;await put('reviews',structuredClone(r));await put('visits',v);await refresh()}closeSheet();go('reviewEditor',r.id);return}let a=assessments.find(x=>x.id===v.assessmentId);if(a){drafts.set(a.id,structuredClone(a));closeSheet();go('observation',a.id);return}closeSheet();route={view:'setup',id:l.id,visitId:v.id};render();scrollTo(0,0)}
function visitCard(v){const l=learners.find(x=>x.id===v.learnerId),valid=!!l;const disabled=(label,path)=>`<button class="icon-action disabled" disabled aria-disabled="true" aria-label="${label}">${actionIcon(label,path)}</button>`,mapPath='M12 2a7 7 0 0 0-7 7c0 5 7 13 7 13s7-8 7-13a7 7 0 0 0-7-7zm0 10a3 3 0 1 1 0-6 3 3 0 0 1 0 6z',visitPath='M5 3h10l4 4v14H5zm9 1v4h4M8 12h8M8 16h8';return `<article class="visit-card ${VISIT_TYPES[v.type]?.colour}"><div class=visit-details><strong>${esc(l?.name||'Unknown learner')}</strong><b>${VISIT_TYPES[v.type]?.label}</b><small>${longVisitDate(v)}${v.time?` · ${v.time}`:''}</small>${v.location?`<address>${esc(v.location)}</address>`:''}</div><div class=visit-actions>${v.location?`<a class=icon-action href="${googleMapsUrl(v.location)}" target=_blank rel="noopener" aria-label="Directions for ${esc(l?.name)}">${actionIcon('Directions',mapPath)}</a>`:disabled('Directions unavailable — location missing',mapPath)}${valid?`<button class=icon-action data-open-visit="${v.id}" aria-label="Open visit for ${esc(l.name)}">${actionIcon('Open Visit',visitPath)}</button>`:disabled('Open Visit unavailable — learner or visit missing',visitPath)}${l?`<button class=icon-action data-profile="${v.learnerId}" aria-label="View learner ${esc(l.name)}">${actionIcon('View learner','M12 12a4 4 0 1 0 0-8 4 4 0 0 0 0 8zm-7 9a7 7 0 0 1 14 0')}</button>`:disabled('View learner unavailable — learner missing','M12 12a4 4 0 1 0 0-8 4 4 0 0 0 0 8zm-7 9a7 7 0 0 1 14 0')}<button class=icon-action data-edit-visit="${v.id}" aria-label="Edit visit for ${esc(l?.name||'unknown learner')}">${actionIcon('Edit visit','M4 20l4-1 11-11-3-3L5 16zm10-13 3 3')}</button></div></article>`}
function planning(){const days=rollingFiveDays(new Date()),upcoming=upcomingVisits(visits);return `<div class=page-title><div><small class=eyebrow>VISITS</small><h1>Planning</h1></div><button class=secondary data-toggle-calendar>${calendarOpen?'Close Calendar':'Open Calendar'}</button></div><div class=planning-key aria-label="Planning colour key">${Object.values(VISIT_TYPES).map((x,i)=>`${i?'<i aria-hidden=true>·</i>':''}<span class=${x.colour}>${x.label}</span>`).join('')}</div>${calendarOpen?calendar():''}<section class="card working-week"><h2>Next five days</h2><div class=week-grid>${days.map((date,i)=>`<div class="${i===0?'today':''} rolling-day" data-rolling-date="${date}" ${i===0?'aria-current="date"':''}><b>${new Intl.DateTimeFormat('en-GB',{weekday:'short'}).format(new Date(`${date}T12:00:00`))}</b><small>${Number(date.slice(-2))}</small><span class=rolling-visits>${visitsForDate(visits,date).map(v=>visitChip(v,learners.find(l=>l.id===v.learnerId))).join('')}</span></div>`).join('')}</div></section><section><h2>Upcoming Visits</h2>${upcoming.length?upcoming.map(visitCard).join(''):'<section class=card><p class=muted>No upcoming visits planned.</p></section>'}</section>`}
function backupDate(value){return value?new Intl.DateTimeFormat('en-GB',{dateStyle:'long',timeStyle:'short'}).format(new Date(value)):'No backup recorded yet'}
function toolkit(){return `<div class=page-title><div><small class=eyebrow>SECONDARY TOOLS</small><h1>Toolkit</h1></div></div><section class="card backup-card"><small class=eyebrow>BACKUP & RESTORE</small><h2>Protect your Assessor+ data</h2><p class=muted>Keep a portable backup somewhere secure.</p><p><strong>Last successful backup:</strong><br>${backupDate(assessorProfile.lastSuccessfulBackup)}</p><div class=button-row><button class=action data-backup>Download Backup</button><label class=secondary>Restore Backup<input class=visually-hidden id=restore-backup type=file accept=".zip,application/zip"></label></div><p class=muted>This backup may contain learner personal data and assessment evidence. Store it only in an approved secure location.</p></section><section class="card app-device"><h2>App & Device</h2><button id=install-app class=secondary ${deferredInstallPrompt?'':'hidden'}>Install Assessor+</button><p class=muted>Install Assessor+ on this device for quick offline access.</p></section><section class=toolkit-grid><article class=tool-tile><span aria-hidden=true>＋</span><strong>More tools later</strong><small>Assessor tools such as CadMate can be added here.</small></article></section><button class=settings-row data-view=settings><span aria-hidden=true>⚙</span><span><strong>Settings</strong><small>Profile, preferences and local storage</small></span><b>›</b></button>`}
function settings(){return `<button class=text-button data-view=toolkit>‹ Toolkit</button><h1>Settings</h1><section class=settings-list><button data-assessor-profile><span><strong>General</strong><small>Profile and application preferences</small></span><b>›</b></button><article><span><strong>Notifications / Backup Reminder</strong><small>Choose how often Assessor+ recommends a local backup.</small><select id=backup-reminder><option value=weekly ${assessorProfile.backupReminder==='weekly'?'selected':''}>Weekly</option><option value=monthly ${assessorProfile.backupReminder==='monthly'?'selected':''}>Monthly</option><option value=off ${assessorProfile.backupReminder==='off'?'selected':''}>Off</option></select></span></article><article><span><strong>Learning Support</strong><small>Assessor assistance uses the existing evidence and mapping presentation. It does not change mapping results, thresholds or assessment validity.</small></span></article><article><span><strong>Admin</strong><small>App Information · Assessor+ V0.8.1 · ${navigator.onLine?'Offline-ready; currently online':'Working offline'}</small><small>Local records: ${learners.length} learners · ${assessments.length} assessments · ${assessments.reduce((n,a)=>n+(a.media?.length||0)+(a.knowledgeEvidence?.length||0),0)} media · ${professionalDocuments.length} professional documents</small></span></article></section>`}
function signatureEditor(){return `${assessorProfile.signatureDataUrl?`<img class=signature-preview src="${assessorProfile.signatureDataUrl}" alt="Saved assessor signature"><div class=button-row><button type=button class=secondary data-replace-signature>Replace Signature</button><button type=button class="text-button danger" data-remove-profile-signature>Clear Signature</button></div>`:`<div class=signature-pad-wrap><canvas id=signature-pad aria-label="Draw assessor signature"></canvas><div class=button-row><button type=button class=secondary data-clear-signature>Clear</button><button type=button class=action data-save-signature>Save Signature</button></div></div>`}`}
function documentRows(){return professionalDocuments.length?professionalDocuments.map(d=>`<article class=document-row><span><strong>${esc(d.name)}</strong><small>${esc(d.documentType)}${d.expiryDate?` · Expires ${formatUKDate(d.expiryDate)}`:''}</small></span><div><button type=button class=text-button data-view-document="${d.id}">View</button><button type=button class="text-button danger" data-delete-document="${d.id}">Delete</button></div></article>`).join(''):'<p class=muted>No professional documents stored.</p>'}
function courseOptions(selected=""){return [...courses.values()].map(c=>`<option value="${c.course.id}" ${c.course.id===selected?'selected':''}>${esc(c.course.title)}</option>`).join('')}
function optionalOptions(course,selected=""){return isKsbCourse(course)?'':course.course.optionalUnitIds.map(id=>course.units.find(u=>u.id===id)).filter(Boolean).map(u=>`<option value="${u.id}" ${u.id===selected?'selected':''}>${u.id} — ${esc(u.title)}</option>`).join('')}
function learnerList(){const first=[...courses.values()][0],showOptional=!isKsbCourse(first),groups=groupLearnersByCourse(learners,learnerCourse);return `<div class=page-title><h1>Learners</h1><button class="action small" data-toggle-add>Add Learner</button></div><section class="card add-learner" hidden><h2>Add Learner</h2><form id=learner-form><label>Learner name<input name=name required></label><label>Workplace / site address<input name=workplace autocomplete=street-address></label><label>Course<select name=course required>${courseOptions()}</select></label><label data-optional-unit ${showOptional?'':'hidden'}>Optional unit<select name=optional ${showOptional?'required':''}><option value="">Select optional unit</option>${optionalOptions(first)}</select></label><label data-pathway hidden>Pathway<select name=pathway><option value="">Select pathway</option></select></label><button class=action>Save Learner</button></form></section>${groups.length?groups.map(group=>`<section class="learner-group"><h2>${esc(group.title)}</h2><div class=list-card>${group.learners.map(l=>`<button class=learner-row data-profile="${l.id}"><span><strong><i class="status-dot ${learnerPlanningStatus(l,visits)}" aria-hidden=true></i>${esc(String(l.name||'').trim())}</strong></span><b aria-hidden=true>›</b></button>`).join('')}</div></section>`).join(''):'<section class=list-card><p class=empty>No learners yet.</p></section>'}`}
function profileSnapshot(l){const course=learnerCourse(l),next=upcomingVisits(visits).find(v=>v.learnerId===l.id);if(isKsbCourse(course)){const p=deriveKsbProgress(course,l,assessments).overall;return `<div class=profile-snapshot><span><small>Progress</small><strong>${p.assessed} / ${p.total} KSBs</strong></span><span><small>Next planned activity</small><strong>${next?`${VISIT_TYPES[next.type].label} · ${formatUKDate(next.date)}`:'Not planned'}</strong></span></div>`}const units=deriveUnitProgress(course,l,assessments),average=units.length?Math.round(units.reduce((n,x)=>n+x.percentage,0)/units.length):0;return `<div class=profile-snapshot><span><small>Qualification progress</small><strong>${average}% average</strong></span><span><small>Next planned activity</small><strong>${next?`${VISIT_TYPES[next.type].label} · ${formatUKDate(next.date)}`:'Not planned'}</strong></span></div>`}
function availabilitySection(l){const leave=Array.isArray(l.annualLeave)?l.annualLeave:[],college=l.collegeDays||{},names=['Sunday','Monday','Tuesday','Wednesday','Thursday','Friday','Saturday'];return `<section class="card availability-section"><div class=section-head><h2>Planning / Availability</h2><button class="secondary small" data-manage-availability="${l.id}">Manage</button></div><dl><div><dt>Next Review</dt><dd>${esc(upcomingVisits(visits).find(v=>v.learnerId===l.id&&['review','combined'].includes(v.type))?.date?formatUKDate(upcomingVisits(visits).find(v=>v.learnerId===l.id&&['review','combined'].includes(v.type)).date):'Not planned')}</dd></div><div><dt>Next Observation / Visit</dt><dd>${esc(upcomingVisits(visits).find(v=>v.learnerId===l.id)?.date?formatUKDate(upcomingVisits(visits).find(v=>v.learnerId===l.id).date):'Not planned')}</dd></div><div><dt>Planned College Day(s)</dt><dd>${(college.weekdays||[]).map(d=>names[d]).join(', ')||'None'}${(college.dates||[]).length?` · ${(college.dates||[]).map(formatUKDate).join(', ')}`:''}</dd></div><div><dt>Annual Leave</dt><dd>${leave.length?leave.map(x=>x.startDate===(x.endDate||x.startDate)?formatUKDate(x.startDate):`${formatUKDate(x.startDate)} – ${formatUKDate(x.endDate)}`).join('<br>'):'None recorded'}</dd></div></dl></section>`}
function availabilityForm(l){const leave=Array.isArray(l.annualLeave)?l.annualLeave:[],college=l.collegeDays||{};return `<h2 id=sheet-title>Planning / Availability</h2><form id=availability-form data-learner-id="${l.id}"><fieldset><legend>Planned College Days</legend>${['Monday','Tuesday','Wednesday','Thursday','Friday'].map((name,i)=>`<label class=check-row><input type=checkbox name=collegeWeekday value="${i+1}" ${(college.weekdays||[]).includes(i+1)?'checked':''}> ${name}</label>`).join('')}<label>One-off College Dates <small>Comma separated YYYY-MM-DD dates</small><input name=collegeDates value="${esc((college.dates||[]).join(', '))}"></label></fieldset><fieldset><legend>Annual Leave</legend><div id=annual-leave-rows>${leave.map(x=>`<div class=leave-row data-leave-id="${x.id}"><label>From<input type=date name=leaveStart value="${x.startDate}" required></label><label>To<input type=date name=leaveEnd value="${x.endDate||x.startDate}" required></label><button type=button class="text-button danger" data-delete-leave="${x.id}">Delete</button></div>`).join('')}</div><button type=button class=secondary data-add-leave>Add Annual Leave</button></fieldset><button class=action>Save Availability</button></form>`}
function courseSubtitle(course){const c=course.course,title=String(c.title||'').split(/\s+-\s+(?=(?:ST|Version|Level)\b)/)[0];return [title,c.reference,c.version?`Version ${c.version}`:'',c.level?`Level ${c.level}`:''].filter(Boolean).join(' · ')}
const pct=value=>Math.max(0,Math.min(100,Math.round(Number(value)||0)));
function progressRings(l,course){const ksb=isKsbCourse(course),snapshot=latestFullReviewProgress(reviews,l,course,ksb),names=ksb?['KSBs','OTJ','Time','EPA']:['LOs','GLH','Time'],metrics=snapshot?.metrics||progressMetrics(ksb).map(([key],i)=>({key,label:names[i],value:null,colour:['green','blue','orange','purple'][i]})),radii=metrics.map((_,i)=>52-i*10);return `<button class="course-progress ${snapshot?'':'not-recorded'}" data-matrix="${l.id}" aria-label="Open ${isKsbCourse(course)?'KSB ':''}Evidence Matrix"><span class=profile-section-title>Course Progress</span><small class=progress-source>${snapshot?`From Full Review · ${formatUKDate(snapshot.review.reviewDate)}`:'Not recorded yet · Add at next Full Review'}</small><span class=ring-layout><svg class=progress-rings viewBox="0 0 120 120" aria-hidden=true>${metrics.map((m,i)=>`<circle class=ring-track cx=60 cy=60 r=${radii[i]} pathLength=100></circle>${m.value===null?'':`<circle class="ring-value ${m.colour}" cx=60 cy=60 r=${radii[i]} pathLength=100 style="--progress:${m.value}"></circle>`}`).join('')}<circle class=ring-centre cx=60 cy=60 r=${radii.at(-1)-6}></circle></svg><span class=ring-key>${metrics.map(m=>`<span><i class=${m.colour}></i><b>${m.label}</b><strong>${m.value===null?'—':`${m.value}%`}</strong></span>`).join('')}</span></span></button>`}
function assessmentBars(l,course){let rows;if(isKsbCourse(course)){const records=assessments.filter(a=>a.learnerId===l.id&&(a.courseId||DEFAULT_COURSE_ID)===course.course.id).sort((a,b)=>String(a.date).localeCompare(String(b.date))),total=activeKSBs(course,l,'knowledge').length+activeKSBs(course,l,'skills').length+activeKSBs(course,l,'behaviours').length;rows=records.map((a,i)=>({label:`EP${i+1}`,value:pct(total?validKsbEvidence(a).length/total*100:0)}))}else rows=deriveUnitProgress(course,l,assessments).map(x=>({label:x.unit.id,value:x.percentage}));return `<button class=assessment-progress data-history="${l.id}" aria-label="Open Assessment History"><span class=profile-section-title>Assessment Progress</span><small class=progress-source>From Assessor+ observations</small><span class=assessment-bars style="--bar-count:${Math.max(rows.length,1)}">${rows.map(x=>`<span class=assessment-bar><b>${x.value}%</b><i><i style="--progress:${pct(x.value)}"></i></i><em>${esc(x.label)}</em></span>`).join('')||'<small>No observations yet</small>'}</span></button>`}
function visitTypeSheet(l){const catchup=reviewsForLearner(reviews,l.id).some(r=>!isCatchUpReview(r)&&r.catchUpRequired==='Yes');return `<h2 id=sheet-title>Plan a Visit</h2><p class=muted>${esc(l.name)} · choose a visit type</p><div class=visit-type-options>${Object.entries(VISIT_TYPES).filter(([type])=>type!=='catchup'||catchup).map(([type,x])=>`<button class=secondary data-select-visit-type="${type}" data-learner-id="${l.id}"><i class="status-dot ${type}"></i>${x.label}</button>`).join('')}</div>`}
const historyRow=v=>`<button class=visit-history-row data-open-history="${v.id}"><strong>${formatUKDate(v.date)}</strong><span><i class="status-dot ${v.type}"></i>${esc(VISIT_TYPES[v.type]?.label||'Visit')}</span></button>`;
function visitHistory(l){const rows=actualVisitHistory({learnerId:l.id,reviews,assessments,visits}),shown=rows.slice(0,5);return `<section class=visit-history><h2>Visit History</h2>${shown.length?shown.map(historyRow).join(''):'<p class=muted>No visits recorded</p>'}${rows.length>5?`<button class=text-button data-view-all-visits="${l.id}">View all</button>`:''}</section>`}
function editLearnerProfile(l){const course=learnerCourse(l);return `<h2 id=sheet-title>Edit Profile</h2><form id=learner-profile-form data-learner-id="${l.id}"><label>Learner name<input name=name value="${esc(l.name)}" required autocomplete=name></label><label>Employer<input name=employer value="${esc(l.employer||'')}"></label><label>Workplace / address<input name=workplace value="${esc(l.workplace||'')}" autocomplete=street-address></label><label>Course<select name=course required>${courseOptions(l.courseId||course.course.id)}</select></label><label>Optional unit<select name=optional><option value="">None</option>${optionalOptions(course,l.optionalUnitId)}</select></label><button class=action>Save Profile</button></form><hr><button class=secondary data-manage-availability="${l.id}">College Days & Annual Leave</button><div class=edit-profile-management><h3>Learner management</h3>${l.status==='withdrawn'?`<button class=secondary data-reinstate-learner="${l.id}">Reinstate Learner</button>`:`<button class=secondary data-withdraw-learner="${l.id}">Withdraw Learner</button>`}<button class="text-button danger" data-delete-learner="${l.id}">Delete Learner</button></div>`}
function learnerProfile(id){const l=learners.find(x=>x.id===id);if(!l)return learnerList();const course=learnerCourse(l),past=actualVisitHistory({learnerId:l.id,reviews,assessments,visits})[0],next=nextPlannedVisit(visits,l.id),visitBox=(title,v,empty)=>v?`<button class=next-visit-card data-open-visit="${v.id}"><h3>${title}</h3><strong>${formatUKDate(v.date)}</strong><small>${esc(VISIT_TYPES[v.type]?.label||'Visit')}</small></button>`:`<article><h3>${title}</h3><strong class=muted>${empty}</strong></article>`;return `<button class="text-button back-control" data-view=learners>‹ Learners</button><main class=learner-profile><header class=learner-profile-header><div><h1>${esc(l.name)}</h1><p>${esc(courseSubtitle(course))}</p></div><button class=profile-edit data-edit-profile="${l.id}" aria-label="Edit Profile"><svg viewBox="0 0 24 24" aria-hidden=true><path d="M4 20h4L19 9l-4-4L4 16v4zm9.5-13.5 4 4"></path></svg></button></header>${progressRings(l,course)}${assessmentBars(l,course)}<section class=visits-overview><div>${visitBox('Last Visit',past,'No previous visit')}${visitBox('Next Visit',next,'Nothing planned')}</div></section><button class="action plan-a-visit" data-plan-visit="${l.id}">Plan a Visit</button>${visitHistory(l)}</main>`}

function learnerManagement(l){return `<section class="card learner-management"><h2>Learner management</h2><p class=muted>Withdrawal retains assessments, reviews and history. Permanent deletion is a separate action.</p><div class=button-row>${l.status==='withdrawn'?`<button class=secondary data-reinstate-learner="${l.id}">Reinstate Learner</button>`:`<button class=secondary data-withdraw-learner="${l.id}">Withdraw Learner</button>`}<button class="text-button danger" data-delete-learner="${l.id}">Delete Learner</button></div></section>`}
function reviewSummary(l){const rows=reviewsForLearner(reviews,l.id),latest=rows[0];return `<section class="card reviews-card"><div class=section-head><div><h2>Reviews</h2><small>${latest?`Latest ${formatUKDate(latest.reviewDate)} · Next ${formatUKDate(latest.nextReviewDate)}`:'No reviews saved'}</small></div><button class="action small" data-new-review="${l.id}">New Review</button></div>${rows.length?`<div class=review-history>${rows.map(r=>`<article><span><strong>${esc(r.reviewType||'Progress Review')} · ${r.id}</strong><small>${formatUKDate(r.reviewDate)} · ${esc(r.assessor?.judgement||r.status)}${r.nextReviewDate?` · Next ${formatUKDate(r.nextReviewDate)}`:''}</small></span><div><button class=text-button data-open-review="${r.id}">View / Edit</button><button class=text-button data-review-pdf="${r.id}">PDF</button><button class="text-button danger" data-delete-review="${r.id}">Delete</button></div></article>`).join('')}</div>`:'<p class=muted>Reviews are stored locally in this learner profile and do not require QR or cloud transfer.</p>'}</section>`}
const reviewOption=(value,options)=>options.map(x=>`<option ${x===value?'selected':''}>${x}</option>`).join('');
function reviewProgress(r){const s=r.snapshot;if(s.type==='KSB')return `<div class=review-progress>${['knowledge','skills','behaviours','overall'].map(k=>`<span><strong>${k[0].toUpperCase()+k.slice(1)}</strong><b>${s[k].assessed} / ${s[k].total}</b></span>`).join('')}</div>`;return `<div class=review-progress><span><strong>Qualification progress</strong><b>${s.overall.assessed} / ${s.overall.total} (${s.overall.percentage}%)</b></span>${s.units.map(u=>`<span><strong>${u.id}</strong><b>${u.assessed} / ${u.total}</b></span>`).join('')}</div>`}
function reviewEditor(id){const r=reviews.find(x=>x.id===id);if(!r)return learnerList();if(isCatchUpReview(r))return catchUpEditor(r);const l=learners.find(x=>x.id===r.learnerId),ksb=r.snapshot.type==='KSB',text=(n,label,v)=>`<label>${label}<textarea name="${n}" rows=3>${esc(v)}</textarea></label>`,select=(n,label,v,opts)=>`<label>${label}<select name="${n}">${reviewOption(v,opts)}</select></label>`;return `${backToLearnerButton(l.id)}<div class=assessment-heading><div><h1>${esc(r.reviewType)}</h1><small>${r.id} · ${esc(r.identitySnapshot.learnerName)}</small></div><span class=draft-state>${r.status}</span></div><form id=review-form data-review-id="${r.id}" class=review-form><section class=card><h2>Review details</h2><p><strong>${esc(r.identitySnapshot.qualification)}</strong>${r.identitySnapshot.pathway?`<br>Pathway: ${esc(r.identitySnapshot.pathway)}`:''}<br>${esc(r.identitySnapshot.employer||'Employer not recorded')} · ${esc(r.identitySnapshot.assessor)}</p><div class="grid two"><label>Review date<input name=reviewDate ${UK_DATE_INPUT_ATTRIBUTES} value="${r.reviewDate}" required></label><label>Previous review date<input value="${formatUKDate(r.previousReviewDate)}" disabled></label><label>Next review date<input name=nextReviewDate ${UK_DATE_INPUT_ATTRIBUTES} value="${r.nextReviewDate}" ${ksb?'required':''}></label></div><p class="review-warning" ${nextReviewWarning(r)?'':'hidden'}>The next review is more than 6 months after this review. Confirm that this arrangement has been checked. <label class=check-row><input type=checkbox name=warningAcknowledged ${r.nextReviewWarningAcknowledged?'checked':''}> Acknowledged by assessor</label></p></section><section class="card catch-up-plan"><h2>Interim monitoring</h2><label>Catch-up review required before next review?<select name=catchUpRequired>${reviewOption(r.catchUpRequired||'No',['No','Yes'])}</select></label><label class=catch-up-date ${r.catchUpRequired==='Yes'?'':'hidden'}>Proposed Catch-up Review date<input type=date name=catchUpDate value="${r.catchUpDate||''}"></label><p class=muted>When required, this is planned automatically halfway to the next full review. You can change the date.</p></section><details class=card open><summary><h2>Progress snapshot</h2></summary>${reviewProgress(r)}<button type=button class=secondary data-matrix="${l.id}">View detailed progress</button></details><details class="card apprentice-progress" open><summary><h2>Apprentice+ Progress</h2></summary>${progressMetrics(ksb).map(([key,label])=>{const previous=r.apprenticeProgress?.previous?.[key],current=r.apprenticeProgress?.current?.[key],change=progressChange(previous,current);return `<label><strong>${label}</strong><span class=progress-comparison>Previous: <b>${previous==null?'Not recorded':`${previous}%`}</b> · Current: <b>${current==null?'Not recorded':`${current}%`}</b> · Change: <b>${change==null?'Not recorded':`${change>0?'+':''}${change} percentage points`}</b></span><input type=number name="apprenticeProgress_${key}" min=0 max=100 step=0.1 value="${current??''}" placeholder="Optional"></label>`}).join('')}</details><details class=card open><summary><h2>Progress since last review</h2></summary>${text('achievements','Key achievements / progress',r.progress.achievements)}${text('newLearning','New learning or evidence',r.progress.newLearning)}${text('development','Areas still requiring development',r.progress.development)}</details><details class=card><summary><h2>Apprentice comments</h2></summary>${text('apprenticeComments','How do you feel you are progressing?',r.apprentice.comments)}${select('apprenticeConcern','Any concerns or support needed?',r.apprentice.concern,['No concerns','Support/concern raised'])}${text('apprenticeConcernNotes','Support / concern notes',r.apprentice.concernNotes)}</details><details class=card><summary><h2>Employer / workplace comments</h2></summary>${select('employerRating','Workplace progress rating',r.employer.rating,['Ahead of plan','On track','Some concerns','Significant concern'])}${text('employerComments','How is the apprentice progressing in the workplace?',r.employer.comments)}</details><details class=card open><summary><h2>Assessor comments</h2></summary>${select('assessorJudgement','Progress judgement',r.assessor.judgement,['Ahead of plan','On track','Requires support','At risk'])}${text('assessorComments','Assessor comments',r.assessor.comments)}<p class=muted>This review judgement does not mark KSBs or assessment criteria as evidenced.</p></details>${ksb?`<details class=card><summary><h2>Off-the-job training</h2></summary>${text('otjStatus','OTJ progress / status',r.otj.status)}${select('otjPlanned','Is planned OTJ training taking place?',r.otj.planned,['Yes','No / concern'])}${select('otjRelevant','Is OTJ learning relevant to occupational KSB development?',r.otj.relevant,['Yes','No / concern'])}${text('otjComments','Apprentice comments on quality / quantity',r.otj.comments)}${text('otjConcernNotes','Concern notes',r.otj.concernNotes)}</details><details class=card><summary><h2>English & Maths</h2></summary>${select('english','English',r.englishMaths.english,['Not required / already achieved','Working towards','Achieved','Concern'])}${text('englishNotes','English notes',r.englishMaths.englishNotes)}${select('maths','Maths',r.englishMaths.maths,['Not required / already achieved','Working towards','Achieved','Concern'])}${text('mathsNotes','Maths notes',r.englishMaths.mathsNotes)}</details>`:''}<details class=card><summary><h2>Mandatory qualifications</h2></summary>${select('mandatoryStatus','Status',r.mandatoryQualification?.status||'Not applicable',['On track','Achieved','Concern','Not applicable'])}${text('mandatoryNotes','Notes',r.mandatoryQualification?.notes||'')}</details><details class=card><summary><h2>Wellbeing & Support</h2></summary>${select('support','Is any additional support required?',r.wellbeing.support,['No','Yes'])}${select('safeguarding','Any safeguarding or wellbeing concern to record?',r.wellbeing.safeguarding,['No','Yes'])}${text('wellbeingNotes','Concise notes / action',r.wellbeing.notes)}<p class=muted>This review is not a replacement for the provider’s formal safeguarding reporting procedure.</p></details><details class=card open><summary><h2>${esc(r.readiness.label)}</h2></summary>${select('readiness','Assessor judgement',r.readiness.status,ksb?['Not yet ready','Developing towards readiness','Nearly ready','Ready for gateway/completion review']:['Not yet ready','Developing towards completion','Nearly complete','Ready for completion review'])}${text('readinessNotes','Supporting notes',r.readiness.notes)}<p class=muted>${ksb?'This is readiness only and does not state or imply that EPA has been passed.':'This is a neutral qualification completion judgement.'}</p></details><details class=card open><summary><h2>Targets / action plan</h2></summary><div id=review-targets>${(r.targets||[]).map((t,i)=>targetRow(t,i)).join('')}</div><button type=button class=secondary data-add-target>Add Target</button></details><details class=card><summary><h2>Training plan</h2></summary>${select('trainingChange','Does the training plan need to change?',r.trainingPlan.change,['No','Yes'])}${text('trainingNotes','Change / action notes',r.trainingPlan.notes)}</details><details class=card open><summary><h2>Sign-off</h2></summary><div class="grid two"><label>Apprentice name<input name=apprenticeSignName value="${esc(r.signatures.apprentice?.name||r.identitySnapshot.learnerName)}"></label><button type=button class=secondary data-sign-review=apprentice>${r.signatures.apprentice?'Signed':'Sign as Apprentice'}</button><label>Employer representative<input name=employerSignName value="${esc(r.signatures.employer?.name||r.employer.representativeName)}"></label><label>Employer role<input name=employerSignRole value="${esc(r.signatures.employer?.role||r.employer.representativeRole)}"></label><button type=button class=secondary data-sign-review=employer>${r.signatures.employer?'Signed':'Sign as Employer'}</button><label>Assessor / reviewer<input name=assessorSignName value="${esc(r.signatures.assessor?.name||r.identitySnapshot.assessor)}"></label><button type=button class=secondary data-sign-review=assessor>${r.signatures.assessor?'Signed':'Add Saved Assessor Signature'}</button></div></details><div class=assessment-actions><button type=button class=secondary data-save-review-draft>Save Draft</button><button type=submit class=action>Complete Review</button>${reviews.some(x=>x.id===r.id)?`<button type=button class=secondary data-review-pdf="${r.id}">Download PDF</button>`:''}</div></form>`}
function catchUpEditor(r){const l=learners.find(x=>x.id===r.learnerId);return `${backToLearnerButton(l.id)}<div class=assessment-heading><div><h1>Catch-up Review</h1><small>${r.id} · ${esc(r.identitySnapshot.learnerName)}</small></div><span class=draft-state>${r.status}</span></div><form id=review-form data-review-id="${r.id}" class="review-form catch-up-form"><section class=card><h2>Catch-up details</h2><p><strong>${esc(r.identitySnapshot.learnerName)}</strong><br>${esc(r.identitySnapshot.qualification)}</p><div class="grid two"><label>Catch-up Review date<input type=date name=reviewDate value="${r.reviewDate}" required></label><label>Previous full review date<input type=date value="${r.previousReviewDate}" disabled></label><label>Next full review date<input type=date value="${r.nextReviewDate}" disabled></label><label>Contact method <em>Optional</em><select name=contactMethod><option value="">Select method</option>${reviewOption(r.contactMethod||'',['In person','Phone','Video call','Other'])}</select></label></div></section><section class=card><h2>Progress check</h2><label>Current position<select name=progressCheck>${reviewOption(r.progressCheck||'On track',['On track','Improving','No change','Falling further behind'])}</select></label></section><section class=card><h2>Previous actions</h2>${(r.previousActions||[]).length?(r.previousActions||[]).map((a,i)=>`<article class=catch-up-action><strong>${esc(a.action)}</strong><small>${esc(a.owner||'')} · ${formatUKDate(a.targetDate)}</small><label>Status<select name=previousActionStatus>${reviewOption(a.status||'Not completed',['Completed','In progress','Not completed'])}</select></label></article>`).join(''):'<p class=muted>No outstanding actions from the previous full review.</p>'}</section><section class=card><h2>Short notes</h2><label>What has improved?<textarea name=improved rows=2>${esc(r.notes?.improved||'')}</textarea></label><label>What is still causing concern?<textarea name=concern rows=2>${esc(r.notes?.concern||'')}</textarea></label><label>What needs to happen before the full review?<textarea name=beforeFullReview rows=2>${esc(r.notes?.beforeFullReview||'')}</textarea></label></section><section class=card><h2>Next actions</h2><div id=review-targets>${(r.targets||[]).map((t,i)=>catchUpTargetRow(t,i)).join('')}</div><button type=button class=secondary data-add-target>Add Action</button></section><div class=assessment-actions><button type=button class=secondary data-save-review-draft>Save Draft</button><button type=submit class=action>Complete Catch-up</button><button type=button class=secondary data-review-pdf="${r.id}">Download PDF</button></div></form>`}
function catchUpTargetRow(t={},i=0){return `<article class=target-row data-target-row><label>Action<textarea name=targetAction rows=2>${esc(t.action||'')}</textarea></label><div class="grid two"><label>Owner<input name=targetOwner value="${esc(t.owner||'')}" placeholder="Learner, employer or assessor"></label><label>Target date<input type=date name=targetDate value="${t.targetDate||''}"></label></div><button type=button class="text-button danger" data-remove-target>Remove</button></article>`}
function captureCatchUp(r,form=$('#review-form')){if(!r||!form)return false;const f=new FormData(form),date=readUKDate(form.elements.reviewDate);if(date===null)return false;r.reviewDate=date;r.progressCheck=f.get('progressCheck');r.contactMethod=f.get('contactMethod');r.notes={improved:f.get('improved').trim(),concern:f.get('concern').trim(),beforeFullReview:f.get('beforeFullReview').trim()};const statuses=f.getAll('previousActionStatus');r.previousActions=(r.previousActions||[]).map((a,i)=>({...a,status:statuses[i]||a.status}));const actions=f.getAll('targetAction'),owners=f.getAll('targetOwner'),dates=f.getAll('targetDate');r.targets=actions.map((action,i)=>({id:r.targets?.[i]?.id||crypto.randomUUID(),action:action.trim(),owner:owners[i]?.trim()||'',targetDate:dates[i]||'',status:'Open'})).filter(t=>t.action||t.targetDate);return true}
async function syncCatchUpPlan(full){
 const existing=reviews.find(x=>isCatchUpReview(x)&&x.sourceFullReviewId===full.id),related=visits.filter(v=>v.sourceFullReviewId===full.id);let catchUp=existing;
 if(full.catchUpRequired==='Yes'&&full.catchUpDate){const learner=learners.find(x=>x.id===full.learnerId),course=learnerCourse(learner);catchUp=existing?{...existing,reviewDate:full.catchUpDate,previousReviewDate:full.reviewDate,nextReviewDate:full.nextReviewDate}:createCatchUpReview({reviews,learner,course,fullReview:full,date:full.catchUpDate});await put('reviews',catchUp);full.catchUpReviewId=catchUp.id}else if(existing?.status==='Draft')await remove('reviews',existing.id);
 const planned=plannedReviewVisits(full,related).map(v=>v.type==='catchup'?{...v,reviewId:catchUp?.id||v.reviewId}:v);for(const visit of related)if(!planned.some(v=>v.id===visit.id))await remove('visits',visit.id);for(const visit of planned)await put('visits',{...visit,location:visit.location||learners.find(x=>x.id===full.learnerId)?.workplace||'',updatedAt:new Date().toISOString()});full.catchUpVisitId=planned.find(v=>v.type==='catchup')?.id||'';full.nextReviewVisitId=planned.find(v=>v.type==='review')?.id||'';await put('reviews',structuredClone(full));
}
function targetRow(t={},i=0){return `<article class=target-row data-target-row><label>Action / target<textarea name=targetAction rows=2>${esc(t.action||'')}</textarea></label><div class="grid two"><label>Owner<select name=targetOwner>${reviewOption(t.owner||'Apprentice',['Apprentice','Employer','Assessor/Provider'])}</select></label><label>Target date<input name=targetDate ${UK_DATE_INPUT_ATTRIBUTES} value="${t.targetDate||''}"></label><label>Status<select name=targetStatus>${reviewOption(t.status||'Open',['Open','Completed','Carried forward'])}</select></label></div>${t.sourceReviewId?`<small>Carried from ${t.sourceReviewId}</small>`:''}<button type=button class="text-button danger" data-remove-target>Remove</button></article>`}
function assessmentList(learnerId){const rows=assessments.filter(a=>!learnerId||a.learnerId===learnerId).sort((a,b)=>b.date.localeCompare(a.date)||b.id.localeCompare(a.id));return `${learnerId?backToLearnerButton(learnerId):''}<h1>Assessments</h1><section class=list-card>${rows.length?rows.map(a=>{const l=learners.find(x=>x.id===a.learnerId),course=learnerCourse(l),ksb=isKsbCourse(course),u=course.units?.find(x=>x.id===a.primaryUnit),date=formatUKDate(a.date);return `<button class=history-row data-open="${a.id}"><time>${date}</time><span><strong>${a.id}</strong><b>${ksb?'Holistic Observation':`Unit ${u.id} · ${esc(u.title)}`}</b><small>${ksb?`${validKsbEvidence(a).length} KSBs evidenced`:`${a.hasDiscussion?'Observation + Discussion':'Observation'} · ${evidencedEntries(a).length} ACs evidenced`}</small><small>${esc(l?.name)}</small></span><em>›</em></button>`}).join(''):'<p class=empty>No saved assessments.</p>'}</section>`}
function setup(learnerId){const l=learners.find(x=>x.id===learnerId),course=learnerCourse(l),plannedDate=visits.find(v=>v.id===route.visitId)?.date||new Date().toISOString().slice(0,10);if(isKsbCourse(course))return `${backToLearnerButton(l.id)}<h1>New Holistic Observation</h1><form id=setup-form class=card data-visit-id="${route.visitId||''}"><input type=hidden name=learner value="${l.id}"><input type=hidden name=unit value=KSB><label>Learner<input value="${esc(l.name)}" disabled></label><p class=muted>${esc(course.course.title)}${pathwayForLearner(course,l)?`<br>Pathway: ${esc(pathwayForLearner(course,l).title)}`:''}<br>On-programme portfolio evidence — this is not an EPA assessment.</p><div class="grid two"><label>Observation date<input name=date ${UK_DATE_INPUT_ATTRIBUTES} value="${plannedDate}" required></label><label>Assessor<input name=assessor value="${esc(assessorProfile.name)}" required></label></div><button class=action>Continue</button></form>`;const preselected=route.primaryUnit,progress=deriveUnitProgress(course,l,assessments);return `${backToLearnerButton(l.id)}<h1>New Observation</h1><form id=setup-form class=card data-visit-id="${route.visitId||''}"><input type=hidden name=learner value="${l.id}"><label>Learner<input value="${esc(l.name)}" disabled></label><fieldset class=unit-selector><legend>Primary unit</legend>${progress.map(p=>`<label class=unit-option><input type=radio name=unit value="${p.unit.id}" ${preselected===p.unit.id?'checked':''} required><span class=unit-option-content><span class=unit-option-heading><strong>${p.unit.id} · ${esc(conciseUnitTitle(p.unit))}</strong><b>${p.percentage}%</b></span></span></label>`).join('')}</fieldset><div class="grid two"><label>Assessment date<input name=date ${UK_DATE_INPUT_ATTRIBUTES} value="${plannedDate}" required></label><label>Assessor<input name=assessor value="${esc(assessorProfile.name)}" required></label></div><button class=action>Continue</button></form>`}
function assessorProfileView(){return `<button class=text-button data-view=settings>‹ General</button><section class="card assessor-profile"><small class=eyebrow>GENERAL / PROFILE</small><h1>Assessor Profile</h1><form id=assessor-profile-form><label>Assessor Name<input name=name value="${esc(assessorProfile.name)}" required></label><label>Provider Name <em>Optional</em><input name=provider value="${esc(assessorProfile.providerName)}"></label><h2>Provider Logo</h2>${providerLogoUrl?`<img class=provider-logo src="${providerLogoUrl}" alt="Provider logo"><button type=button class="text-button danger" data-remove-logo>Remove Logo</button>`:`<label class=file-button>Add Logo<input hidden id=profile-logo type=file accept="image/png,image/jpeg,image/webp"></label>`}<h2>Saved Signature</h2>${signatureEditor()}<button class=action>Save Profile</button></form></section><section class=card><div class=section-head><h2>Professional Documents</h2><button class="secondary small" data-add-document>Add Document</button></div><p class=muted>Certificates, your current CV and CPD files stay offline and on this device.</p>${documentRows()}</section>`}
function preview(s){const t=String(s).replace(/\s+/g,' ').trim();return t.length>105?t.slice(0,102).replace(/\s+\S*$/,'')+'…':t}
function criterionRows(a,kind){const course=assessmentCourse(a),mappingTable=courseMappings(course),u=course.units.find(x=>x.id===a.primaryUnit),learner=learners.find(x=>x.id===a.learnerId),matrix=previousEvidenceMatrix(course,learner,assessments,a.id);return `<div class=lo-list>${u.learningOutcomes.map(lo=>{const cs=lo.criteria.filter(x=>x.evidenceClass===kind);if(!cs.length)return'';const count=cs.filter(x=>a.selected[kind].includes(x.id)).length,open=openLO[kind]===lo.id;return `<section class="lo-section ${open?'open':''}"><button type=button class=lo-toggle data-lo="${kind}|${lo.id}" aria-expanded="${open}"><span><strong>LO${lo.id}</strong> · ${esc(preview(lo.wording))}</span><b>${count}/${cs.length}</b></button>${open?`<div class=lo-content>${cs.map(ac=>{const selected=a.selected[kind].includes(ac.id),evidenced=previousEvidenceFor(matrix,u.id,ac.id).length>0;return `<div class="criterion ${selected?'selected':evidenced?'previously-evidenced':''}"><label><input type=checkbox data-ac="${kind}:${ac.id}" ${selected?'checked':''}><span><strong>AC${ac.id}</strong><small>${esc(preview(ac.wording))}</small></span>${evidenced?'<i class=evidence-tick aria-label="Previously evidenced">✓</i>':''}</label><button type=button class=detail-button data-detail="${u.id}|${lo.id}|${ac.id}" aria-label="View full wording for AC${ac.id}">Details</button>${mappingHtml(a,kind,ac.id)}</div>`}).join('')}</div>`:''}</section>`}).join('')}</div>`}
function mappingHtml(a,kind,ac){const course=assessmentCourse(a),mappingTable=courseMappings(course);if(!a.selected[kind].includes(ac))return'';const rows=filterActiveMappings(mappingsFor(mappingTable,a.primaryUnit,ac),course,learners.find(l=>l.id===a.learnerId)).map(m=>{const saved=a.mappings[kind].find(x=>x.sourceAC===ac&&x.targetUnit===m.targetUnit&&x.targetAC===m.targetAC),decision=m.mappingType==='automatic'?'automatic':saved?.decision;if(decision==='ignored')return'';const accepted=decision==='automatic'||decision==='confirmed';return `<button type=button class="map-chip ${accepted?'accepted':'pending'}" data-map="${kind}|${ac}|${m.targetUnit}|${m.targetAC}">${accepted?'✓':'?'} ${m.targetUnit}-AC${m.targetAC}</button>`}).join('');const active=activeUnitIds(course,learners.find(l=>l.id===a.learnerId)),ignored=a.mappings[kind].filter(m=>m.sourceAC===ac&&m.decision==='ignored'&&active.has(m.targetUnit));return rows||ignored.length?`<div class=related><span>Related</span>${rows}${ignored.length?`<button type=button class=revisit data-revisit="${kind}|${ac}">Review ignored (${ignored.length})</button>`:''}</div>`:''}
const mediaIcon=name=>({camera:'<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M4 7h3l2-3h6l2 3h3v12H4z"/><circle cx="12" cy="13" r="4"/></svg>',video:'<svg viewBox="0 0 24 24" aria-hidden="true"><rect x="3" y="6" width="13" height="12" rx="2"/><path d="m16 10 5-3v10l-5-3z"/></svg>',gallery:'<svg viewBox="0 0 24 24" aria-hidden="true"><rect x="3" y="4" width="18" height="16" rx="2"/><circle cx="9" cy="9" r="2"/><path d="m4 17 5-5 4 4 2-2 5 4"/></svg>',audio:'<svg viewBox="0 0 24 24" aria-hidden="true"><rect x="9" y="3" width="6" height="12" rx="3"/><path d="M5 11a7 7 0 0 0 14 0M12 18v3M8 21h8"/></svg>',file:'<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M6 3h8l4 4v14H6zM14 3v5h4M9 13h6M9 17h6"/></svg>'}[name]);
const mediaLabel=(name,label,input)=>`<label class=media-control>${mediaIcon(name)}<span>${label}</span>${input}</label>`;
function ksbRows(a,collection,label){const course=assessmentCourse(a),learner=assessmentLearner(a),previous=previousKsbEvidence(course,learner,assessments,a.id);return `<section class=ksb-section><h2>${label}</h2>${activeKSBs(course,learner,collection).map(k=>{const selected=(a.selectedKSBs||[]).includes(k.reference),entries=previous.get(k.reference)||[];return `<label class="criterion ksb ${selected?'selected':entries.length?'previously-evidenced':''}"><input type=checkbox data-ksb="${k.reference}" ${selected?'checked':''}><span><strong>${k.reference}</strong><small>${esc(k.wording)}</small>${entries.length?`<i>${entries.map(e=>`${esc(e.assessmentId)} · ${e.method} · ${formatUKDate(e.date)}`).join('<br>')}</i>`:''}</span></label>`}).join('')}</section>`}
function observation(id){const a=drafts.get(id)||assessments.find(x=>x.id===id);if(!a)return assessmentList();const l=learners.find(x=>x.id===a.learnerId),course=learnerCourse(l);if(isKsbCourse(course))return ksbObservation(a,l,course);const u=course.units.find(x=>x.id===a.primaryUnit);return `${backToLearnerButton(l.id)}<div class=assessment-heading><div><h1>${a.id}</h1><small>${esc(l.name)} · Unit ${u.id}</small></div><span class=draft-state>${assessments.some(x=>x.id===a.id)?'Saved record':'Draft'}</span></div><section class="card assessment-meta"><strong>${esc(u.title)}</strong><div class="grid two"><label>Date<input id=date ${UK_DATE_INPUT_ATTRIBUTES} value="${a.date}"></label><label>Assessor<input id=assessor value="${esc(a.assessor)}"></label></div></section><section class=card><h2>Practical Observation</h2>${criterionRows(a,'practical')}<label>Observation Notes<textarea id=notes placeholder="Record the observed activity and evidence…">${esc(a.notes)}</textarea></label></section><section class=card><div class=section-head><h2>Practical Evidence</h2><span>${(a.media||[]).length} items</span></div><div class=media-actions>${mediaLabel('camera','Camera','<input class="visually-hidden practical-media" type=file accept="image/*" capture=environment>')}${mediaLabel('video','Video','<input class="visually-hidden practical-media" type=file accept="video/*" capture=environment>')}<button type=button class=secondary data-record-video>Record Optimised Video</button>${mediaLabel('gallery','Gallery','<input class="visually-hidden practical-media" type=file accept="image/*,video/*" multiple>')}</div><div id=recording-status></div><div class=media-grid>${(a.media||[]).map(m=>`<button type=button class=media-item data-media="${m.id}">${m.kind==='photo'?`<img src="${m.url}" alt="${m.reference}">`:`<video muted preload=metadata src="${m.url}"></video>`}<small>${m.reference.split('-').at(-1)}</small></button>`).join('')}</div></section><section class=card>${a.hasDiscussion?`<div class=section-head><h2>Professional Discussion</h2><button type=button class=text-button data-remove-pd>Remove</button></div>${criterionRows(a,'knowledge')}<label>Discussion Notes<textarea id=discussionNotes>${esc(a.discussionNotes)}</textarea></label><h2>Knowledge Evidence</h2><div class="media-actions knowledge-media-actions"><button type=button class="secondary media-control" data-record-audio>${mediaIcon('audio')}<span>Record Audio</span></button>${mediaLabel('file','Files','<input class="visually-hidden knowledge-files" type=file accept="audio/*,.pdf,.doc,.docx,.txt" multiple>')}</div><div id=recording-status></div><div class=knowledge-list>${(a.knowledgeEvidence||[]).map(m=>`<article><strong>${m.reference.split('-').at(-1)} · ${m.kind==='audio'?'Audio':esc(m.name)}</strong>${m.kind==='audio'?`<audio controls preload=metadata src="${m.url}"></audio>`:`<a href="${m.url}" target=_blank>View</a>`}<button type=button class=text-button data-remove-knowledge="${m.id}">Remove</button></article>`).join('')}</div>`:'<button type=button class=secondary data-add-pd>Add Professional Discussion</button>'}</section><section class=card><h2>Assessment Decision</h2><label>Outcome<select id=outcome><option value="">Select outcome</option><option ${a.outcome==='Competent evidence demonstrated'?'selected':''}>Competent evidence demonstrated</option><option ${a.outcome==='Further evidence required'?'selected':''}>Further evidence required</option></select></label><h2>Assessor Feedback</h2><textarea id=feedback data-original="${esc(a.feedback)}" placeholder="Enter assessor feedback…">${esc(a.feedback)}</textarea><div class=signature><h2>Assessor Signature</h2>${a.signatureSnapshot?`<img class=signature-preview src="${a.signatureSnapshot.dataUrl}" alt="Assessment signature"><p><strong>${esc(a.assessor)}</strong><br>Signed ${formatUKDate(a.signatureDate)}</p>`:a.signature?`<p>Legacy typed signature: <strong>${esc(a.signature)}</strong><br>${formatUKDate(a.signatureDate)}</p>`:`<button type=button class=secondary data-add-saved-signature ${assessorProfile.signatureDataUrl?'':'disabled'}>Add Saved Signature</button>`}</div>${assessments.some(x=>x.id===a.id)?`<button type=button class=secondary data-pdf="${a.id}">Generate PDF</button><button type=button class=action data-zip="${a.id}">Download Evidence ZIP</button><button type=button class=text-button data-delete-observation="${a.id}">Delete Observation</button>`:''}</section><div class=assessment-actions><button type=button class=action data-save="${a.id}">Save Observation</button></div>`}
function knowledgeRows(a){const course=assessmentCourse(a),learner=assessmentLearner(a),previous=previousKsbEvidence(course,learner,assessments,a.id),discussion=a.theoryKnowledge?.professionalDiscussion||[],files=a.theoryKnowledge?.supportingFiles||[];return `<section class="ksb-section theory-knowledge"><h3>Knowledge</h3>${activeKSBs(course,learner,'knowledge').map(k=>{const discussionSelected=discussion.includes(k.reference),fileSelected=files.includes(k.reference),current=discussionSelected||fileSelected,entries=previous.get(k.reference)||[];return `<div class="criterion ksb ${current?'selected':entries.length?'previously-evidenced':''}"><span class=ksb-wording><strong>${k.reference}</strong><small>${esc(k.wording)}</small>${entries.length?`<i>✓ ${entries.map(e=>`${esc(e.assessmentId)} · ${e.method} · ${formatUKDate(e.date)}`).join('<br>')}</i>`:''}</span><div class=theory-methods aria-label="Evidence methods for ${k.reference}"><label><input type=checkbox data-theory-ksb="professionalDiscussion|${k.reference}" ${discussionSelected?'checked':''} ${a.hasDiscussion?'':'disabled'}> Professional Discussion</label><label><input type=checkbox data-theory-ksb="supportingFiles|${k.reference}" ${fileSelected?'checked':''}> Supporting File</label></div></div>`}).join('')}</section>`}
